import type { SoftwareProfile } from "@/lib/software";

type Entry = {
  slug: string;
  name: string;
  category: string;
  tagline: string;
  summary: string;
  officialUrl: string;
  pricingUrl: string;
  freePlan: string;
  pricingSummary: string;
  bestFor: string[];
  features: string[];
  strengths: string[];
  tradeoffs: string[];
  comparisons?: { title: string; href: string }[];
};

function profile(entry: Entry): SoftwareProfile {
  return {
    slug: entry.slug,
    name: entry.name,
    category: entry.category,
    tagline: entry.tagline,
    summary: entry.summary,
    productImage: {
      src: `https://www.google.com/s2/favicons?domain=${new URL(entry.officialUrl).hostname}&sz=256`,
      alt: `${entry.name} official product icon`,
      caption: "Official product icon. Visit the vendor website for current interface screenshots and demonstrations.",
      sourceUrl: entry.officialUrl,
    },
    bestFor: entry.bestFor,
    keyFeatures: entry.features,
    strengths: entry.strengths,
    tradeoffs: entry.tradeoffs,
    pricingSummary: entry.pricingSummary,
    freePlan: entry.freePlan,
    officialUrl: entry.officialUrl,
    pricingUrl: entry.pricingUrl,
    comparisons: entry.comparisons ?? [],
    alternatives: [],
    reviewedOn: "November 7, 2026",
  };
}

